/**
 * FSRS-4.5 scheduler vs. golden sequences generated by the reference implementation (py-fsrs 2.5.1).
 * See tests/fixtures/fsrs-4.5/README.md for how the fixture was produced.
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { newCard, review, W, type CardState, type Grade } from '../src/domain/fsrs.ts'

interface Step { grade: Grade; at: string; elapsedDays: number; stability: number; difficulty: number; intervalDays: number | null; reps: number; lapses: number }
interface Golden { reference: { version: string; algorithm: string; weights: number[]; maximumInterval: number }; sequences: { name: string; desiredRetention: number; steps: Step[] }[] }

const golden = JSON.parse(readFileSync(new URL('./fixtures/fsrs-4.5/golden.json', import.meta.url), 'utf8')) as Golden
const close = (a: number, b: number) => Math.abs(a - b) <= 1e-9 * Math.max(1, Math.abs(b))

test('fixture is the FSRS-4.5 reference with our default weights', () => {
  assert.equal(golden.reference.algorithm, 'FSRS-4.5')
  assert.equal(golden.reference.version, '2.5.1')
  assert.deepEqual(golden.reference.weights, [...W])
  assert.ok(golden.sequences.length >= 50 && golden.sequences.reduce((n, s) => n + s.steps.length, 0) >= 400)
})

test('stability, difficulty, interval, reps and lapses match the reference for every review', () => {
  for (const seq of golden.sequences) {
    let card: CardState = newCard(new Date(seq.steps[0]!.at))
    seq.steps.forEach((st, i) => {
      const now = new Date(st.at)
      const next = review(card, st.grade, now, seq.desiredRetention, golden.reference.maximumInterval)
      const where = `${seq.name} step ${i} (grade ${st.grade}, elapsed ${st.elapsedDays}d)`
      assert.ok(close(next.stability, st.stability), `${where}: S ${next.stability} != ${st.stability}`)
      assert.ok(close(next.difficulty, st.difficulty), `${where}: D ${next.difficulty} != ${st.difficulty}`)
      const days = (next.due.getTime() - now.getTime()) / 86_400_000
      // reference "again" goes to minute-level relearning; the product schedules the next day (documented deviation)
      assert.equal(days, st.intervalDays ?? 1, `${where}: interval`)
      assert.equal(next.reps, st.reps, `${where}: reps`)
      assert.equal(next.lapses, st.lapses, `${where}: lapses`)
      card = next
    })
  }
})
